"""Apply OmniVoice Studio's audited Seed-VC realtime optimizations."""

import base64
import subprocess
import sys
import tempfile
from pathlib import Path

PATCH = base64.b64decode(
    ""
)


def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: apply-seed-vc-optimizations.py SEED_VC_DIR")
    seed_vc_dir = Path(sys.argv[1]).resolve()
    with tempfile.NamedTemporaryFile(suffix=".patch", delete=False) as handle:
        handle.write(PATCH)
        patch_path = Path(handle.name)
    try:
        check = subprocess.run(
            ["git", "-C", str(seed_vc_dir), "apply", "--check", str(patch_path)],
            check=False,
            capture_output=True,
            text=True,
        )
        if check.returncode != 0:
            reverse_check = subprocess.run(
                [
                    "git",
                    "-C",
                    str(seed_vc_dir),
                    "apply",
                    "--reverse",
                    "--check",
                    str(patch_path),
                ],
                check=False,
                capture_output=True,
                text=True,
            )
            if reverse_check.returncode == 0:
                print("Seed-VC optimizations are already applied.")
                return 0
            raise RuntimeError(
                "Seed-VC optimization patch does not match the pinned checkout:\n"
                + check.stderr
            )
        subprocess.run(
            [
                "git",
                "-C",
                str(seed_vc_dir),
                "apply",
                "--whitespace=nowarn",
                str(patch_path),
            ],
            check=True,
        )
    finally:
        patch_path.unlink(missing_ok=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
